import React, { useState, useMemo } from 'react';
import { REGIONS, parseEventDate, getRegion } from '../data/timeline';
import EventDetailPage from './EventDetailPage';

const getEventType = (id, types) => (types || []).find(t => t.id === id) || { id, label: id, color: '#8a8680', bg: '#f2f0ec' };

// ── Era label ─────────────────────────────────────────────────────
function eraLabel(year) {
  if (year === null || year === undefined || isNaN(year)) return 'Unknown date';
  if (year < -3000) return 'Prehistoric / early civilisation';
  if (year < -500)  return 'Ancient world (before 500 BCE)';
  if (year < 0)     return 'Classical antiquity (500–1 BCE)';
  if (year < 500)   return 'Late antiquity (1–500 CE)';
  if (year < 1000)  return 'Early medieval (500–1000)';
  if (year < 1500)  return 'Medieval (1000–1500)';
  if (year < 1800)  return 'Early modern (1500–1800)';
  if (year < 1900)  return 'Nineteenth century (1800–1900)';
  if (year < 2100)  return `${Math.floor(year / 10) * 10}s`;
  return 'Future';
}

// ── Researcher badges ─────────────────────────────────────────────
function EventBadges({ event, allEvents }) {
  const bookCount = (event.bookIds || []).length;
  // Contested: another event shares a tag and overlapping books but different date framing
  const sharedTagEvents = allEvents.filter(e =>
    e.id !== event.id &&
    e.tags?.some(t => event.tags?.includes(t)) &&
    (e.bookIds || []).some(b => (event.bookIds || []).includes(b))
  );
  const isContested = sharedTagEvents.length > 0 && sharedTagEvents.some(e => e.dateRaw !== event.dateRaw);

  return (
    <div style={{ display: 'flex', gap: 4, flexWrap: 'wrap', marginTop: 4 }}>
      {bookCount === 1 && (
        <span title="Only one source discusses this event — seek corroboration"
          style={{ fontSize: 9, padding: '1px 7px', borderRadius: 8, background: '#faf0dc', color: '#b07d28', fontFamily: 'var(--font-mono)', fontStyle: 'normal', border: '1px solid #b07d2844' }}>
          ◉ single witness
        </span>
      )}
      {isContested && (
        <span title="Sources give conflicting accounts of this event"
          style={{ fontSize: 9, padding: '1px 7px', borderRadius: 8, background: '#faeae8', color: '#c0392b', fontFamily: 'var(--font-mono)', fontStyle: 'normal', border: '1px solid #c0392b44' }}>
          ⊘ contested
        </span>
      )}
      {bookCount >= 3 && (
        <span title="Well-corroborated — multiple sources agree"
          style={{ fontSize: 9, padding: '1px 7px', borderRadius: 8, background: '#e4f4ec', color: '#2e7d5e', fontFamily: 'var(--font-mono)', fontStyle: 'normal', border: '1px solid #2e7d5e44' }}>
          ⊕ corroborated
        </span>
      )}
    </div>
  );
}

// ── Event card ────────────────────────────────────────────────────
function EventCard({ event, books, onEdit, eventTypes, onTagClick, onSelect, allEvents }) {
  const region  = getRegion(event.region);
  const evType  = getEventType(event.type, eventTypes);
  const parsed  = parseEventDate(event.dateRaw);
  const linkedBooks = books.filter(b => (event.bookIds || []).includes(b.id));

  return (
    <div style={{ background: 'var(--paper-2)', border: `1px solid var(--paper-3)`, borderLeft: `3px solid ${region.color}`, borderRadius: 8, padding: '12px 14px', cursor: 'pointer', transition: 'border-color 0.12s, box-shadow 0.12s', position: 'relative' }}
      onClick={() => onSelect?.(event.id)}
      onMouseEnter={e => { e.currentTarget.style.borderColor = region.color + '88'; e.currentTarget.style.boxShadow = 'var(--shadow-sm)'; const el = e.currentTarget.querySelector('.ev-actions'); if (el) el.style.opacity = '1'; }}
      onMouseLeave={e => { e.currentTarget.style.borderColor = 'var(--paper-3)'; e.currentTarget.style.boxShadow = 'none'; const el = e.currentTarget.querySelector('.ev-actions'); if (el) el.style.opacity = '0'; }}>

      {/* Badge row */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 7, flexWrap: 'wrap', paddingRight: 50 }}>
        <span style={{ fontSize: 10, padding: '2px 7px', borderRadius: 12, background: evType.bg + '33', color: evType.color, border: `1px solid ${evType.color}44`, fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>{evType.label}</span>
        <span style={{ fontSize: 10, padding: '2px 7px', borderRadius: 12, background: region.color + '22', color: region.color, fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>{region.label}</span>
        {linkedBooks.length > 0 && (
          <span style={{ fontSize: 10, color: 'var(--ink-4)', display: 'flex', alignItems: 'center', gap: 3 }}>
            {linkedBooks.slice(0, 3).map(b => <span key={b.id} style={{ display: 'inline-block', width: 6, height: 6, borderRadius: '50%', background: b.color }} />)}
            <span style={{ fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>{linkedBooks.length} book{linkedBooks.length !== 1 ? 's' : ''}</span>
          </span>
        )}
      </div>

      {/* Title */}
      <div style={{ fontSize: 13, fontWeight: 500, color: 'var(--ink)', marginTop: 6, lineHeight: 1.4 }}>{event.title}</div>

      {/* Researcher badges */}
      <EventBadges event={event} allEvents={allEvents} />

      {/* Tags */}
      {event.tags?.length > 0 && (
        <div style={{ display: 'flex', gap: 5, flexWrap: 'wrap', marginTop: 6 }}>
          {event.tags.map(tag => (
            <button key={tag} onClick={e => { e.stopPropagation(); onTagClick?.(tag); }}
              style={{ fontSize: 10, padding: '2px 8px', borderRadius: 20, background: 'var(--paper-3)', color: 'var(--ink-3)', fontFamily: 'var(--font-mono)', border: 'none', cursor: 'pointer' }}
              onMouseEnter={e => { e.currentTarget.style.background = 'var(--accent-light)'; e.currentTarget.style.color = 'var(--accent)'; }}
              onMouseLeave={e => { e.currentTarget.style.background = 'var(--paper-3)'; e.currentTarget.style.color = 'var(--ink-3)'; }}>
              #{tag}
            </button>
          ))}
        </div>
      )}

      <div style={{ fontSize: 10, color: 'var(--ink-4)', marginTop: 5, fontStyle: 'italic' }}>Click to open perspectives →</div>

      <div className="ev-actions" style={{ position: 'absolute', top: 8, right: 10, display: 'flex', gap: 4, opacity: 0, transition: 'opacity 0.15s' }}>
        <button onClick={e => { e.stopPropagation(); onEdit(event); }}
          style={{ fontSize: 10, padding: '2px 8px', borderRadius: 5, background: 'var(--paper-3)', color: 'var(--ink-2)', border: 'none', cursor: 'pointer' }}>Edit</button>
      </div>
    </div>
  );
}

// ── BookComparePanel (tag-based) ──────────────────────────────────
function BookComparePanel({ events, books, tag, onClose }) {
  const tagged = events.filter(e => e.tags?.includes(tag) || e.title?.toLowerCase().includes(tag.toLowerCase()));
  const bookIds = [...new Set(tagged.flatMap(e => e.bookIds || []))];
  const relatedBooks = bookIds.map(id => books.find(b => b.id === id)).filter(Boolean);
  if (!relatedBooks.length) return null;
  return (
    <div style={{ borderTop: '1px solid var(--paper-3)', background: 'var(--paper)', flexShrink: 0, maxHeight: 300, display: 'flex', flexDirection: 'column' }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '8px 20px', borderBottom: '1px solid var(--paper-3)', flexShrink: 0 }}>
        <span style={{ fontSize: 11, fontWeight: 500, color: 'var(--ink-2)', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>BOOK COMPARISON · #{tag}</span>
        <span style={{ fontSize: 11, color: 'var(--ink-4)' }}>· {tagged.length} events · {relatedBooks.length} books</span>
        <button onClick={onClose} style={{ marginLeft: 'auto', fontSize: 11, color: 'var(--ink-4)', padding: '2px 8px', border: '1px solid var(--paper-3)', borderRadius: 5, cursor: 'pointer', background: 'transparent' }}>Close ✕</button>
      </div>
      <div style={{ flex: 1, overflowY: 'auto', padding: '10px 20px', display: 'grid', gridTemplateColumns: `repeat(${Math.min(relatedBooks.length, 4)}, 1fr)`, gap: 12 }}>
        {relatedBooks.map(book => {
          const bookEvents = tagged.filter(e => (e.bookIds||[]).includes(book.id));
          return (
            <div key={book.id}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 5, marginBottom: 7 }}>
                <div style={{ width: 7, height: 7, borderRadius: '50%', background: book.color }} />
                <span style={{ fontSize: 11, fontWeight: 500, color: book.color, fontStyle: 'italic' }}>{book.title}</span>
              </div>
              {bookEvents.map(ev => {
                const p = parseEventDate(ev.dateRaw);
                return (
                  <div key={ev.id} style={{ background: 'var(--paper-card)', border: `1px solid ${book.color}33`, borderRadius: 6, padding: '7px 9px', marginBottom: 6 }}>
                    <div style={{ fontSize: 10, color: book.color, fontFamily: 'var(--font-mono)', fontStyle: 'normal', marginBottom: 2 }}>{p.display || '—'}</div>
                    <div style={{ fontSize: 12, fontWeight: 500, color: 'var(--ink)', lineHeight: 1.3 }}>{ev.title}</div>
                  </div>
                );
              })}
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ══ TAB 2: COMPARATIVE VIEW ═══════════════════════════════════════
function ComparativeTab({ events, books, eventTypes, onSelect }) {
  const [selectedBooks, setSelectedBooks] = useState(
    books.slice(0, Math.min(3, books.length)).map(b => b.id)
  );
  const [filterTag, setFilterTag] = useState('');

  const toggleBook = (id) => setSelectedBooks(prev =>
    prev.includes(id) ? prev.filter(b => b !== id) : [...prev, id]
  );

  const compBooks = books.filter(b => selectedBooks.includes(b.id));

  // All events that involve at least one selected book
  const relevantEvents = useMemo(() => {
    return events
      .filter(e => (e.bookIds || []).some(b => selectedBooks.includes(b)))
      .filter(e => !filterTag || e.tags?.includes(filterTag))
      .sort((a, b) => {
        const pa = parseEventDate(a.dateRaw), pb = parseEventDate(b.dateRaw);
        return (pa.sortKey || 0) - (pb.sortKey || 0);
      });
  }, [events, selectedBooks, filterTag]);

  // All tags from relevant events
  const allTags = [...new Set(relevantEvents.flatMap(e => e.tags || []))].sort();

  if (books.length < 2) {
    return (
      <div style={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'var(--ink-4)', fontStyle: 'italic', fontSize: 14 }}>
        Add at least 2 books to events to use the comparative view.
      </div>
    );
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
      {/* Book selector + tag filter */}
      <div style={{ padding: '10px 20px', borderBottom: '1px solid var(--paper-3)', display: 'flex', gap: 8, flexWrap: 'wrap', alignItems: 'center', flexShrink: 0 }}>
        <span style={{ fontSize: 10, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', textTransform: 'uppercase', letterSpacing: '0.06em' }}>Compare:</span>
        {books.map(b => (
          <button key={b.id} onClick={() => toggleBook(b.id)}
            style={{ fontSize: 11, padding: '3px 10px', borderRadius: 20, border: `1px solid ${selectedBooks.includes(b.id) ? b.color : 'var(--paper-3)'}`, background: selectedBooks.includes(b.id) ? b.color + '22' : 'transparent', color: selectedBooks.includes(b.id) ? b.color : 'var(--ink-3)', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 4 }}>
            <span style={{ width: 6, height: 6, borderRadius: '50%', background: selectedBooks.includes(b.id) ? b.color : 'var(--paper-3)', display: 'inline-block' }} />
            {b.title}
          </button>
        ))}
        {allTags.length > 0 && (
          <>
            <div style={{ width: 1, height: 14, background: 'var(--paper-3)' }} />
            <select value={filterTag} onChange={e => setFilterTag(e.target.value)}
              style={{ fontSize: 11, padding: '3px 20px 3px 8px', borderRadius: 6, border: '1px solid var(--paper-3)', background: 'var(--paper-2)', color: 'var(--ink-2)' }}>
              <option value="">All tags</option>
              {allTags.map(t => <option key={t} value={t}>#{t}</option>)}
            </select>
          </>
        )}
        <span style={{ marginLeft: 'auto', fontSize: 11, color: 'var(--ink-4)' }}>{relevantEvents.length} events</span>
      </div>

      {/* Side-by-side grid */}
      {compBooks.length === 0 ? (
        <div style={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'var(--ink-4)', fontStyle: 'italic' }}>Select at least one book above.</div>
      ) : (
        <div style={{ flex: 1, overflow: 'hidden', display: 'flex', flexDirection: 'column' }}>
          {/* Column headers */}
          <div style={{ display: 'grid', gridTemplateColumns: `80px repeat(${compBooks.length}, 1fr)`, gap: '0 8px', padding: '8px 20px', borderBottom: '1px solid var(--paper-3)', flexShrink: 0, background: 'var(--paper-2)' }}>
            <div />
            {compBooks.map(b => (
              <div key={b.id} style={{ display: 'flex', alignItems: 'center', gap: 5 }}>
                <div style={{ width: 8, height: 8, borderRadius: '50%', background: b.color, flexShrink: 0 }} />
                <span style={{ fontSize: 12, fontWeight: 500, color: b.color, fontStyle: 'italic', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{b.title}</span>
              </div>
            ))}
          </div>

          {/* Event rows */}
          <div style={{ flex: 1, overflowY: 'auto', padding: '8px 20px' }}>
            {relevantEvents.length === 0 ? (
              <div style={{ textAlign: 'center', padding: '40px 0', color: 'var(--ink-4)', fontStyle: 'italic' }}>No events match your selection.</div>
            ) : relevantEvents.map(ev => {
              const parsed = parseEventDate(ev.dateRaw);
              return (
                <div key={ev.id} style={{ display: 'grid', gridTemplateColumns: `80px repeat(${compBooks.length}, 1fr)`, gap: '0 8px', marginBottom: 8, alignItems: 'start' }}>
                  {/* Date */}
                  <div style={{ fontSize: 11, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', paddingTop: 8, textAlign: 'right', paddingRight: 8, lineHeight: 1.3 }}>
                    {parsed.display || ev.dateRaw || '—'}
                  </div>
                  {/* Per-book cells */}
                  {compBooks.map(book => {
                    const covered = (ev.bookIds || []).includes(book.id);
                    const bn = (ev.bookNotes || []).find(n => n.bookId === book.id);
                    if (!covered) {
                      return <div key={book.id} style={{ background: 'var(--paper-3)', borderRadius: 6, height: 36, opacity: 0.3 }} />;
                    }
                    return (
                      <div key={book.id} onClick={() => onSelect?.(ev.id)}
                        style={{ background: book.color + '11', border: `1px solid ${book.color}44`, borderLeft: `3px solid ${book.color}`, borderRadius: 6, padding: '7px 10px', cursor: 'pointer' }}
                        onMouseEnter={e => e.currentTarget.style.background = book.color + '22'}
                        onMouseLeave={e => e.currentTarget.style.background = book.color + '11'}>
                        <div style={{ fontSize: 12, fontWeight: 500, color: 'var(--ink)', lineHeight: 1.35, marginBottom: bn?.note ? 3 : 0 }}>{ev.title}</div>
                        {bn?.note && <div style={{ fontSize: 11, color: 'var(--ink-3)', lineHeight: 1.5 }}>{bn.note.slice(0, 80)}{bn.note.length > 80 ? '…' : ''}</div>}
                      </div>
                    );
                  })}
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}

// ══ TAB 3: GAPS & THREADS ═════════════════════════════════════════
function GapsTab({ events, books, eventTypes, onSelect, onTagClick }) {
  const [activeSection, setActiveSection] = useState('witnesses'); // 'witnesses' | 'tags' | 'gaps'

  // ── Single witness events ──
  const singleWitness = events.filter(e => (e.bookIds || []).length === 1);
  const contested = events.filter(e => {
    if ((e.bookIds || []).length < 2) return false;
    return events.some(other =>
      other.id !== e.id &&
      other.tags?.some(t => e.tags?.includes(t)) &&
      other.dateRaw !== e.dateRaw
    );
  });
  const wellCorroborated = events.filter(e => (e.bookIds || []).length >= 3);

  // ── Tag threads ──
  const tagMap = {};
  events.forEach(ev => {
    (ev.tags || []).forEach(tag => {
      if (!tagMap[tag]) tagMap[tag] = { events: [], books: new Set() };
      tagMap[tag].events.push(ev);
      (ev.bookIds || []).forEach(b => tagMap[tag].books.add(b));
    });
  });
  const tagThreads = Object.entries(tagMap)
    .map(([tag, data]) => ({ tag, count: data.events.length, bookCount: data.books.size }))
    .sort((a, b) => b.count - a.count);

  // ── Coverage gaps ──
  // Find books that have events but miss eras covered by other books
  const allEras = [...new Set(events.map(e => {
    const p = parseEventDate(e.dateRaw);
    return p.year !== undefined && p.year !== 0 ? eraLabel(p.year) : null;
  }).filter(Boolean))];

  const bookCoverage = books.map(book => {
    const bookEvents = events.filter(e => (e.bookIds || []).includes(book.id));
    const eras = new Set(bookEvents.map(e => {
      const p = parseEventDate(e.dateRaw);
      return p.year !== undefined && p.year !== 0 ? eraLabel(p.year) : null;
    }).filter(Boolean));
    const missing = allEras.filter(era => !eras.has(era));
    return { book, total: bookEvents.length, covered: eras.size, missing };
  }).filter(bc => bc.missing.length > 0);

  const SectionBtn = ({ id, label, count, color }) => (
    <button onClick={() => setActiveSection(id)}
      style={{ fontSize: 11, padding: '5px 14px', borderRadius: 20, border: `1px solid ${activeSection === id ? color : 'var(--paper-3)'}`, background: activeSection === id ? color + '22' : 'transparent', color: activeSection === id ? color : 'var(--ink-3)', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 5 }}>
      {label} <span style={{ fontSize: 10, opacity: 0.7 }}>{count}</span>
    </button>
  );

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
      {/* Section switcher */}
      <div style={{ padding: '10px 20px', borderBottom: '1px solid var(--paper-3)', display: 'flex', gap: 8, flexShrink: 0, flexWrap: 'wrap' }}>
        <SectionBtn id="witnesses" label="⊘ Witness analysis" count={singleWitness.length + contested.length} color="#c0392b" />
        <SectionBtn id="tags"      label="# Tag threads"       count={tagThreads.length}                     color="#2c5f8a" />
        <SectionBtn id="gaps"      label="◻ Coverage gaps"    count={bookCoverage.length}                   color="#b07d28" />
      </div>

      <div style={{ flex: 1, overflowY: 'auto', padding: '16px 20px' }}>

        {/* ── WITNESS ANALYSIS ── */}
        {activeSection === 'witnesses' && (
          <div>
            {/* Single witness */}
            <div style={{ marginBottom: 24 }}>
              <div style={{ fontSize: 11, fontWeight: 700, color: '#b07d28', fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.07em', textTransform: 'uppercase', marginBottom: 10, paddingBottom: 6, borderBottom: '1px solid var(--paper-3)' }}>
                ◉ Single witness ({singleWitness.length})
              </div>
              <div style={{ fontSize: 11, color: 'var(--ink-4)', fontStyle: 'italic', marginBottom: 12, lineHeight: 1.6 }}>
                These events are discussed by only one source. A researcher should seek corroboration or acknowledge the limitation.
              </div>
              {singleWitness.length === 0 ? (
                <div style={{ fontSize: 12, color: 'var(--ink-4)', fontStyle: 'italic' }}>None — all your events have multiple sources.</div>
              ) : (
                <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
                  {singleWitness.map(ev => {
                    const book = books.find(b => (ev.bookIds||[]).includes(b.id));
                    const p = parseEventDate(ev.dateRaw);
                    return (
                      <div key={ev.id} onClick={() => onSelect?.(ev.id)}
                        style={{ background: 'var(--paper-card)', border: '1px solid #b07d2833', borderLeft: '3px solid #b07d28', borderRadius: 7, padding: '8px 12px', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 10 }}
                        onMouseEnter={e => e.currentTarget.style.background = 'var(--paper-2)'}
                        onMouseLeave={e => e.currentTarget.style.background = 'var(--paper-card)'}>
                        <div style={{ flex: 1 }}>
                          <div style={{ fontSize: 12, fontWeight: 500, color: 'var(--ink)' }}>{ev.title}</div>
                          <div style={{ fontSize: 10, color: 'var(--ink-4)', marginTop: 2, fontStyle: 'italic' }}>{p.display || ev.dateRaw}{book ? ` · ${book.title}` : ''}</div>
                        </div>
                        <span style={{ fontSize: 9, color: '#b07d28', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>single source →</span>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>

            {/* Contested */}
            <div style={{ marginBottom: 24 }}>
              <div style={{ fontSize: 11, fontWeight: 700, color: '#c0392b', fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.07em', textTransform: 'uppercase', marginBottom: 10, paddingBottom: 6, borderBottom: '1px solid var(--paper-3)' }}>
                ⊘ Contested ({contested.length})
              </div>
              <div style={{ fontSize: 11, color: 'var(--ink-4)', fontStyle: 'italic', marginBottom: 12, lineHeight: 1.6 }}>
                Sources share tags but give conflicting dates or framings. Examine these closely.
              </div>
              {contested.length === 0 ? (
                <div style={{ fontSize: 12, color: 'var(--ink-4)', fontStyle: 'italic' }}>No contested events detected.</div>
              ) : contested.map(ev => {
                const p = parseEventDate(ev.dateRaw);
                const evBooks = books.filter(b => (ev.bookIds||[]).includes(b.id));
                return (
                  <div key={ev.id} onClick={() => onSelect?.(ev.id)}
                    style={{ background: 'var(--paper-card)', border: '1px solid #c0392b33', borderLeft: '3px solid #c0392b', borderRadius: 7, padding: '8px 12px', cursor: 'pointer', marginBottom: 6 }}
                    onMouseEnter={e => e.currentTarget.style.background = 'var(--paper-2)'}
                    onMouseLeave={e => e.currentTarget.style.background = 'var(--paper-card)'}>
                    <div style={{ fontSize: 12, fontWeight: 500, color: 'var(--ink)' }}>{ev.title}</div>
                    <div style={{ display: 'flex', gap: 5, marginTop: 4, flexWrap: 'wrap' }}>
                      {evBooks.map(b => <span key={b.id} style={{ fontSize: 10, color: b.color, display: 'flex', alignItems: 'center', gap: 3 }}><span style={{ width: 5, height: 5, borderRadius: '50%', background: b.color, display: 'inline-block' }} />{b.title}</span>)}
                    </div>
                  </div>
                );
              })}
            </div>

            {/* Well-corroborated */}
            <div>
              <div style={{ fontSize: 11, fontWeight: 700, color: '#2e7d5e', fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.07em', textTransform: 'uppercase', marginBottom: 10, paddingBottom: 6, borderBottom: '1px solid var(--paper-3)' }}>
                ⊕ Well corroborated ({wellCorroborated.length})
              </div>
              {wellCorroborated.length === 0 ? (
                <div style={{ fontSize: 12, color: 'var(--ink-4)', fontStyle: 'italic' }}>No events with 3+ sources yet.</div>
              ) : wellCorroborated.map(ev => {
                const evBooks = books.filter(b => (ev.bookIds||[]).includes(b.id));
                return (
                  <div key={ev.id} onClick={() => onSelect?.(ev.id)}
                    style={{ background: 'var(--paper-card)', border: '1px solid #2e7d5e33', borderLeft: '3px solid #2e7d5e', borderRadius: 7, padding: '8px 12px', cursor: 'pointer', marginBottom: 6 }}
                    onMouseEnter={e => e.currentTarget.style.background = 'var(--paper-2)'}
                    onMouseLeave={e => e.currentTarget.style.background = 'var(--paper-card)'}>
                    <div style={{ fontSize: 12, fontWeight: 500, color: 'var(--ink)', marginBottom: 3 }}>{ev.title}</div>
                    <div style={{ display: 'flex', gap: 5, flexWrap: 'wrap' }}>
                      {evBooks.map(b => <span key={b.id} style={{ fontSize: 10, color: b.color, display: 'flex', alignItems: 'center', gap: 3 }}><span style={{ width: 5, height: 5, borderRadius: '50%', background: b.color, display: 'inline-block' }} />{b.title}</span>)}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* ── TAG THREADS ── */}
        {activeSection === 'tags' && (
          <div>
            <div style={{ fontSize: 11, color: 'var(--ink-4)', fontStyle: 'italic', marginBottom: 16, lineHeight: 1.6 }}>
              Threads running across your timeline — click any tag to filter the Chronicle tab.
            </div>
            {tagThreads.length === 0 ? (
              <div style={{ fontSize: 13, color: 'var(--ink-4)', fontStyle: 'italic' }}>No tags on your events yet.</div>
            ) : (
              <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
                {tagThreads.map(({ tag, count, bookCount }) => (
                  <div key={tag}
                    style={{ background: 'var(--paper-card)', border: '1px solid var(--paper-3)', borderRadius: 8, padding: '10px 14px', display: 'flex', alignItems: 'center', gap: 12, cursor: 'pointer' }}
                    onMouseEnter={e => { e.currentTarget.style.borderColor = 'var(--accent-2)'; e.currentTarget.style.background = 'var(--paper-2)'; }}
                    onMouseLeave={e => { e.currentTarget.style.borderColor = 'var(--paper-3)'; e.currentTarget.style.background = 'var(--paper-card)'; }}
                    onClick={() => onTagClick?.(tag)}>
                    <div style={{ flex: 1 }}>
                      <span style={{ fontSize: 13, fontWeight: 500, color: 'var(--accent)', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>#{tag}</span>
                    </div>
                    <div style={{ display: 'flex', gap: 12, fontSize: 11, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>
                      <span><strong style={{ color: 'var(--ink)' }}>{count}</strong> event{count !== 1 ? 's' : ''}</span>
                      <span><strong style={{ color: 'var(--ink)' }}>{bookCount}</strong> book{bookCount !== 1 ? 's' : ''}</span>
                    </div>
                    {bookCount >= 2 && (
                      <span style={{ fontSize: 9, padding: '1px 7px', borderRadius: 8, background: 'var(--accent-light)', color: 'var(--accent)', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>cross-source</span>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* ── COVERAGE GAPS ── */}
        {activeSection === 'gaps' && (
          <div>
            <div style={{ fontSize: 11, color: 'var(--ink-4)', fontStyle: 'italic', marginBottom: 16, lineHeight: 1.6 }}>
              Eras covered by some books but not others — potential blind spots in your reading.
            </div>
            {bookCoverage.length === 0 ? (
              <div style={{ fontSize: 13, color: 'var(--ink-4)', fontStyle: 'italic' }}>No gaps detected — all books cover similar eras, or you only have one book.</div>
            ) : bookCoverage.map(({ book, total, covered, missing }) => (
              <div key={book.id} style={{ background: 'var(--paper-card)', border: `1px solid ${book.color}33`, borderLeft: `3px solid ${book.color}`, borderRadius: 8, padding: '12px 14px', marginBottom: 10 }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 8 }}>
                  <div style={{ width: 8, height: 8, borderRadius: '50%', background: book.color }} />
                  <span style={{ fontSize: 12, fontWeight: 500, color: book.color, fontStyle: 'italic' }}>{book.title}</span>
                  <span style={{ fontSize: 10, color: 'var(--ink-4)', marginLeft: 'auto', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>{total} events · {covered} eras covered</span>
                </div>
                <div style={{ fontSize: 11, color: 'var(--ink-3)', marginBottom: 5 }}>Missing eras compared to your other sources:</div>
                <div style={{ display: 'flex', flexWrap: 'wrap', gap: 5 }}>
                  {missing.map(era => (
                    <span key={era} style={{ fontSize: 10, padding: '2px 8px', borderRadius: 10, background: '#faf0dc', color: '#b07d28', border: '1px solid #b07d2833', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>{era}</span>
                  ))}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

// ══ MAIN TIMELINE VIEW ════════════════════════════════════════════
export default function TimelineView({ events, books, eventTypes, onAdd, onEdit, onUpdate, onManageTypes }) {
  const [activeTab, setActiveTab]     = useState('chronicle');
  const [regionFilter, setRegionFilter] = useState([]);
  const [typeFilter,   setTypeFilter]   = useState([]);
  const [bookFilter,   setBookFilter]   = useState('all');
  const [search,       setSearch]       = useState('');
  const [compareTag,   setCompareTag]   = useState(null);
  const [activeEventId, setActiveEventId] = useState(null);
  const [collapsedEras, setCollapsedEras] = useState({});
  const [sortOrder,    setSortOrder]    = useState('asc');

  const toggleEra = (era) => setCollapsedEras(c => ({ ...c, [era]: !c[era] }));
  const toggleRegion = (id) => setRegionFilter(f => f.includes(id) ? f.filter(r => r !== id) : [...f, id]);
  const toggleType   = (id) => setTypeFilter(f => f.includes(id) ? f.filter(t => t !== id) : [...f, id]);

  // ── Filtered + sorted events for Chronicle ──
  const filtered = useMemo(() => events
    .filter(e => regionFilter.length === 0 || regionFilter.includes(e.region))
    .filter(e => typeFilter.length === 0   || typeFilter.includes(e.type))
    .filter(e => bookFilter === 'all'      || (e.bookIds || []).includes(bookFilter))
    .filter(e => !search || e.title.toLowerCase().includes(search.toLowerCase()) ||
      e.tags?.some(t => t.includes(search.toLowerCase())))
  , [events, regionFilter, typeFilter, bookFilter, search]);

  // ── Group by era ──
  const grouped = useMemo(() => {
    const g = {};
    filtered.forEach(ev => {
      const p = parseEventDate(ev.dateRaw);
      const era = p.year !== undefined ? eraLabel(p.year) : 'Unknown date';
      if (!g[era]) g[era] = [];
      g[era].push(ev);
    });
    Object.keys(g).forEach(era => g[era].sort((a, b) => {
      const pa = parseEventDate(a.dateRaw), pb = parseEventDate(b.dateRaw);
      const diff = (pa.sortKey || 0) - (pb.sortKey || 0);
      return sortOrder === 'asc' ? diff : -diff;
    }));
    return g;
  }, [filtered, sortOrder]);

  const eraOrder = useMemo(() => {
    const keys = Object.keys(grouped);
    return keys.sort((a, b) => {
      const sampleA = grouped[a][0], sampleB = grouped[b][0];
      const pa = parseEventDate(sampleA?.dateRaw), pb = parseEventDate(sampleB?.dateRaw);
      const diff = (pa?.sortKey || 0) - (pb?.sortKey || 0);
      return sortOrder === 'asc' ? diff : -diff;
    });
  }, [grouped, sortOrder]);

  const usedTypes   = [...new Set(events.map(e => e.type).filter(Boolean))];
  const usedRegions = [...new Set(events.map(e => e.region).filter(Boolean))];

  const TABS = [
    { id: 'chronicle',    label: '↔ Chronicle' },
    { id: 'comparative',  label: '⊞ Comparative' },
    { id: 'gaps',         label: '◻ Gaps & threads' },
  ];

  const activeEvent = activeEventId ? events.find(e => e.id === activeEventId) : null;
  if (activeEvent) {
    return (
      <EventDetailPage event={activeEvent} books={books} eventTypes={eventTypes}
        onUpdate={onUpdate} onBack={() => setActiveEventId(null)} />
    );
  }
  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>

      {/* Top bar */}
      <div style={{ padding: '12px 20px 10px', borderBottom: '1px solid var(--paper-3)', flexShrink: 0 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 10 }}>
          <div>
            <div style={{ fontSize: 15, fontWeight: 500, color: 'var(--ink)' }}>Timeline</div>
            <div style={{ fontSize: 11, color: 'var(--ink-3)', fontStyle: 'italic', marginTop: 1 }}>
              {events.length} events · {books.length} sources
            </div>
          </div>
          <div style={{ marginLeft: 'auto', display: 'flex', gap: 6, alignItems: 'center' }}>
            <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search events…"
              style={{ width: 170, padding: '6px 12px', fontSize: 12 }} />
            <button onClick={onAdd} style={{ fontSize: 12, padding: '6px 16px', borderRadius: 7, background: 'var(--accent)', color: 'var(--paper-card)', border: 'none', cursor: 'pointer', whiteSpace: 'nowrap' }}>
              + Add event
            </button>
          </div>
        </div>
      </div>

      {/* Tab bar */}
      <div style={{ display: 'flex', borderBottom: '1px solid var(--paper-3)', flexShrink: 0, background: 'var(--paper-2)', paddingLeft: 8 }}>
        {TABS.map(tab => (
          <button key={tab.id} onClick={() => setActiveTab(tab.id)}
            style={{ fontSize: 11, padding: '8px 18px', border: 'none', borderBottom: `2px solid ${activeTab === tab.id ? 'var(--accent)' : 'transparent'}`, background: 'transparent', color: activeTab === tab.id ? 'var(--accent)' : 'var(--ink-4)', cursor: 'pointer', fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.03em' }}>
            {tab.label}
          </button>
        ))}
      </div>

      {/* ── CHRONICLE TAB ── */}
      {activeTab === 'chronicle' && (
        <div style={{ display: 'flex', flexDirection: 'column', flex: 1, overflow: 'hidden' }}>
          {/* Filter bar */}
          <div style={{ padding: '8px 20px', borderBottom: '1px solid var(--paper-3)', display: 'flex', gap: 6, alignItems: 'center', flexWrap: 'wrap', flexShrink: 0 }}>
            <span style={{ fontSize: 10, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', textTransform: 'uppercase', letterSpacing: '0.06em' }}>Filter:</span>

            {usedRegions.map(r => { const reg = getRegion(r); return (
              <button key={r} onClick={() => toggleRegion(r)}
                style={{ fontSize: 10, padding: '2px 9px', borderRadius: 20, border: `1px solid ${regionFilter.includes(r) ? reg.color : 'var(--paper-3)'}`, background: regionFilter.includes(r) ? reg.color + '22' : 'transparent', color: regionFilter.includes(r) ? reg.color : 'var(--ink-4)', cursor: 'pointer', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>{reg.label}</button>
            );})}

            {usedTypes.length > 0 && <div style={{ width: 1, height: 14, background: 'var(--paper-3)' }} />}
            {usedTypes.map(t => { const et = getEventType(t, eventTypes); return (
              <button key={t} onClick={() => toggleType(t)}
                style={{ fontSize: 10, padding: '2px 9px', borderRadius: 20, border: `1px solid ${typeFilter.includes(t) ? et.color : 'var(--paper-3)'}`, background: typeFilter.includes(t) ? et.color + '22' : 'transparent', color: typeFilter.includes(t) ? et.color : 'var(--ink-4)', cursor: 'pointer', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>{et.label}</button>
            );})}

            {books.length > 0 && <div style={{ width: 1, height: 14, background: 'var(--paper-3)' }} />}
            <select value={bookFilter} onChange={e => setBookFilter(e.target.value)}
              style={{ fontSize: 11, padding: '3px 20px 3px 8px', borderRadius: 6, background: 'var(--paper-2)', color: 'var(--ink-2)', border: '1px solid var(--paper-3)' }}>
              <option value="all">All books</option>
              {books.map(b => <option key={b.id} value={b.id}>{b.title}</option>)}
            </select>

            <button onClick={() => setSortOrder(s => s === 'asc' ? 'desc' : 'asc')}
              style={{ fontSize: 10, padding: '2px 9px', borderRadius: 20, border: '1px solid var(--paper-3)', color: 'var(--ink-4)', cursor: 'pointer', background: 'transparent', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>
              {sortOrder === 'asc' ? '↑ Oldest first' : '↓ Newest first'}
            </button>

            {(regionFilter.length > 0 || typeFilter.length > 0 || bookFilter !== 'all') && (
              <button onClick={() => { setRegionFilter([]); setTypeFilter([]); setBookFilter('all'); }}
                style={{ fontSize: 10, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', cursor: 'pointer', background: 'none', border: 'none' }}>clear</button>
            )}
            <button onClick={onManageTypes} style={{ marginLeft: 'auto', fontSize: 10, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', cursor: 'pointer', background: 'none', border: '1px solid var(--paper-3)', borderRadius: 5, padding: '2px 8px' }}>Manage types</button>
          </div>

          {/* Chronicle feed */}
          <div style={{ flex: 1, overflowY: 'auto', padding: '16px 20px' }}>
            {filtered.length === 0 ? (
              <div style={{ textAlign: 'center', padding: '60px 0', color: 'var(--ink-4)', fontStyle: 'italic' }}>
                {search || regionFilter.length || typeFilter.length ? 'No events match.' : 'No events yet — add your first one.'}
              </div>
            ) : eraOrder.map(era => (
              <div key={era} style={{ marginBottom: 28 }}>
                <button onClick={() => toggleEra(era)}
                  style={{ display: 'flex', alignItems: 'center', gap: 10, width: '100%', background: 'none', border: 'none', cursor: 'pointer', padding: '2px 0', marginBottom: collapsedEras[era] ? 0 : 12, textAlign: 'left' }}>
                  <span style={{ fontSize: 9, color: 'var(--ink-4)', display: 'inline-block', transition: 'transform 0.15s', transform: collapsedEras[era] ? 'rotate(0deg)' : 'rotate(90deg)' }}>▶</span>
                  <div style={{ fontSize: 10, fontWeight: 600, color: 'var(--ink-4)', letterSpacing: '0.08em', textTransform: 'uppercase', fontFamily: 'var(--font-mono)', fontStyle: 'normal', whiteSpace: 'nowrap' }}>{era}</div>
                  <div style={{ flex: 1, height: 1, background: 'var(--paper-3)' }} />
                  <span style={{ fontSize: 10, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)' }}>{grouped[era].length}</span>
                </button>
                {!collapsedEras[era] && (
                  <div style={{ display: 'grid', gridTemplateColumns: '80px 1fr', gap: '0 12px' }}>
                    {grouped[era].map((ev, i) => {
                      const parsed = parseEventDate(ev.dateRaw);
                      return (
                        <React.Fragment key={ev.id}>
                          <div style={{ textAlign: 'right', paddingTop: 10, fontSize: 11, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', lineHeight: 1.3 }}>
                            {parsed.display || '—'}
                          </div>
                          <div style={{ position: 'relative', paddingBottom: i < grouped[era].length - 1 ? 8 : 0 }}>
                            {i < grouped[era].length - 1 && <div style={{ position: 'absolute', left: -7, top: 18, bottom: -4, width: 1, background: 'var(--paper-3)' }} />}
                            <div style={{ position: 'absolute', left: -10, top: 14, width: 7, height: 7, borderRadius: '50%', background: getRegion(ev.region).color, border: '2px solid var(--paper)', flexShrink: 0 }} />
                            <EventCard event={ev} books={books} onEdit={onEdit} eventTypes={eventTypes}
                              onTagClick={tag => setCompareTag(prev => prev === tag ? null : tag)}
                              onSelect={setActiveEventId} allEvents={events} />
                            {i < grouped[era].length - 1 && <div style={{ height: 8 }} />}
                          </div>
                        </React.Fragment>
                      );
                    })}
                  </div>
                )}
              </div>
            ))}
          </div>

          {/* Tag compare panel */}
          {compareTag && <BookComparePanel events={events} books={books} tag={compareTag} onClose={() => setCompareTag(null)} />}
        </div>
      )}

      {/* ── COMPARATIVE TAB ── */}
      {activeTab === 'comparative' && (
        <ComparativeTab events={events} books={books} eventTypes={eventTypes} onSelect={setActiveEventId} />
      )}

      {/* ── GAPS TAB ── */}
      {activeTab === 'gaps' && (
        <GapsTab events={events} books={books} eventTypes={eventTypes}
          onSelect={setActiveEventId}
          onTagClick={tag => { setCompareTag(tag); setActiveTab('chronicle'); }} />
      )}
    </div>
  );
}
